describe('Export Records to CSV', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully export a list of records to CSV', () => {
    // Intercept the CSV export API call
    cy.intercept('GET', '/api/records/export/csv').as('exportCSV');

    // Verify records are displayed
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').should('have.length.greaterThan', 0);

    // Click the export button
    cy.get('[data-testid="export-csv-button"]').click();

    // Wait for the API call
    cy.wait('@exportCSV');

    // Verify success message appears
    cy.get('[data-testid="export-success-message"]')
      .should('be.visible')
      .should('contain', 'Export successful');

    // Verify download link/button appears
    cy.get('[data-testid="download-csv-button"]')
      .should('be.visible')
      .should('contain', 'Download CSV');

    // Verify download link has correct href
    cy.get('[data-testid="download-csv-button"]').should('have.attr', 'href');
    cy.get('[data-testid="download-csv-button"]').should('have.attr', 'href').and('include', '.csv');
  });

  it('should handle empty record list export gracefully', () => {
    // Filter to show no records
    cy.get('[data-testid="filter-input"]').type('nonexistent-filter');
    cy.get('[data-testid="apply-filter-button"]').click();

    // Verify no records are displayed
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').should('not.exist');

    // Intercept the export API call
    cy.intercept('GET', '/api/records/export/csv').as('exportEmptyCSV');

    // Click the export button
    cy.get('[data-testid="export-csv-button"]').click();

    // Wait for the API call
    cy.wait('@exportEmptyCSV');

    // Verify success message appears with appropriate content
    cy.get('[data-testid="export-success-message"]')
      .should('be.visible')
      .should('contain', 'Export successful');

    // Verify download button appears even with empty list
    cy.get('[data-testid="download-csv-button"]')
      .should('be.visible')
      .should('contain', 'Download CSV');

    // Verify download link is present
    cy.get('[data-testid="download-csv-button"]').should('have.attr', 'href');
  });
});
